import InterviewRescheduleDemo from '@/components/shadcn-studio/blocks/interview-reschedule-01/interview-reschedule-01'

const InterviewReschedulePage = () => {
  return <InterviewRescheduleDemo />
}

export default InterviewReschedulePage

'use client'

// React Imports
import type { Ref } from 'react'
import { useEffect, useId, useRef, useState } from 'react'

// Third-party Imports
import {
  CheckIcon,
  CircleCheckBigIcon,
  CopyIcon,
  ExternalLinkIcon,
  HourglassIcon,
  InfoIcon,
  LaptopIcon,
  LinkIcon,
  PlayIcon,
  Share2Icon
} from 'lucide-react'

// Component Imports
import { Button } from '@newtonschool/koyo-ui/button'
import { InputGroup, InputGroupAddon, InputGroupButton, InputGroupInput } from '@newtonschool/koyo-ui/input-group'
import { Spinner } from '@newtonschool/koyo-ui/spinner'

// Util Imports
import { cn } from '@/lib/utils'

import type { FreshLink, InterviewDetails } from './reschedule-data'
import { formatDuration, formatIST, formatLocal, formatRemaining } from './reschedule-data'
import { useInAppBrowser, useIsHandheld, useLocalTimeZone, useNow } from './reschedule-hooks'
import { Banner, blueFocus, Callout, primaryAction } from './reschedule-ui'
import InterviewSummary, { PageHeading } from './interview-summary'

const URGENT_MS = 3 * 3_600_000

const CopyLink = ({ url, showShare }: { url: string; showShare: boolean }) => {
  // States
  const [copyState, setCopyState] = useState<'idle' | 'copied' | 'manual'>('idle')
  const [canShare, setCanShare] = useState(false)

  // Refs
  const inputRef = useRef<HTMLInputElement>(null)

  // Hooks
  const inputId = useId()

  useEffect(() => {
    setCanShare(typeof navigator.share === 'function')
  }, [])

  useEffect(() => {
    if (copyState !== 'copied') return
    const timer = setTimeout(() => setCopyState('idle'), 2500)

    return () => clearTimeout(timer)
  }, [copyState])

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(url)
      setCopyState('copied')
    } catch {
      // In-app browsers (WhatsApp, Instagram) often block the clipboard API — select the text instead.
      inputRef.current?.select()
      setCopyState(document.execCommand?.('copy') ? 'copied' : 'manual')
    }
  }

  const handleShare = async () => {
    try {
      await navigator.share({ title: 'My interview link', url })
    } catch {
      // The candidate closed the share sheet — nothing to do.
    }
  }

  return (
    <div className='space-y-1.5'>
      <label htmlFor={inputId} className='text-muted-foreground text-xs font-medium'>
        Or copy your interview link
      </label>
      <div className='flex gap-2'>
        <InputGroup className='has-[[data-slot=input-group-control]:focus-visible]:border-koyo-color-brand-500 h-10 has-[[data-slot=input-group-control]:focus-visible]:ring-[color-mix(in_oklab,var(--koyo-color-brand-500)_25%,transparent)]'>
          <InputGroupAddon>
            <LinkIcon aria-hidden='true' />
          </InputGroupAddon>
          <InputGroupInput
            ref={inputRef}
            id={inputId}
            readOnly
            value={url}
            onFocus={event => event.currentTarget.select()}
            className='font-mono text-sm'
          />
          <InputGroupAddon align='inline-end'>
            <InputGroupButton
              size='sm'
              variant='ghost'
              className={cn(
                'text-[color-mix(in_oklab,var(--koyo-color-brand-500)_72%,var(--foreground))] hover:bg-[color-mix(in_oklab,var(--koyo-color-brand-500)_10%,var(--background))]',
                blueFocus
              )}
              onClick={handleCopy}
              aria-label='Copy interview link'
            >
              {copyState === 'copied' ? <CheckIcon aria-hidden='true' /> : <CopyIcon aria-hidden='true' />}
              {copyState === 'copied' ? 'Copied' : 'Copy'}
            </InputGroupButton>
          </InputGroupAddon>
        </InputGroup>
        {showShare && canShare && (
          <Button variant='outline' size='icon-lg' onClick={handleShare} aria-label='Share link'>
            <Share2Icon aria-hidden='true' />
          </Button>
        )}
      </div>
      <p role='status' className={cn('text-muted-foreground text-xs', copyState === 'idle' && 'sr-only')}>
        {copyState === 'copied' && 'Link copied. Open it in Chrome to start your interview.'}
        {copyState === 'manual' && 'Couldn’t copy automatically. Press and hold the link above to copy it.'}
      </p>
    </div>
  )
}

/** Shown inside WhatsApp/Instagram-style in-app browsers, which often block the camera and microphone. */
export const InAppBrowserNotice = () => {
  const inApp = useInAppBrowser()

  if (!inApp) return null

  return (
    <Callout tone='info' icon={ExternalLinkIcon} title='Open this page in Chrome.'>
      The browser inside apps like WhatsApp can block your camera and microphone. Copy the link and open it in Chrome
      before you start.
    </Callout>
  )
}

type Props = {
  interview: InterviewDetails
  freshLink: FreshLink
  justIssued: boolean
  alreadyUsedNotice?: boolean
  headingRef?: Ref<HTMLHeadingElement>

  /** Server time minus device time, in ms, so a wrong device clock can't end the countdown early. */
  clockOffset?: number

  /** The server re-checked this deadline and said the link still works; trust it over the local countdown. */
  deadlineConfirmed?: boolean

  /** Called when the countdown reaches zero, so the page can re-check the authoritative status. */
  onDeadlinePassed?: (deadline: string) => void
}

const FreshLinkView = ({
  interview,
  freshLink,
  justIssued,
  alreadyUsedNotice,
  headingRef,
  clockOffset = 0,
  deadlineConfirmed,
  onDeadlinePassed
}: Props) => {
  // Hooks
  const now = useNow()
  const handheld = useIsHandheld()
  const localTimeZone = useLocalTimeZone()

  const rawRemaining = now === null ? null : new Date(freshLink.expiresAt).getTime() - (now + clockOffset)

  // Once the server has confirmed the link still works, never show it as expired on this page.
  const remaining = rawRemaining !== null && deadlineConfirmed ? Math.max(rawRemaining, 30_000) : rawRemaining
  const expired = remaining !== null && remaining <= 0
  const urgent = remaining !== null && !expired && remaining < URGENT_MS
  const needsLaptop = interview.kind === 'coding' && handheld

  useEffect(() => {
    if (expired) onDeadlinePassed?.(freshLink.expiresAt)
  }, [expired, freshLink.expiresAt, onDeadlinePassed])

  return (
    <div className='space-y-6'>
      <div className='space-y-5'>
        <PageHeading headingRef={headingRef}>
          {justIssued ? 'Your new interview link is ready' : 'Your new interview link is still active'}
        </PageHeading>
        <InterviewSummary interview={interview} />
      </div>

      <Banner
        tone={expired ? 'neutral' : urgent ? 'warning' : 'success'}
        icon={urgent ? HourglassIcon : CircleCheckBigIcon}
      >
        <div className='flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5'>
          <p>
            {urgent ? 'Start soon — before ' : 'Start your interview before '}
            <time dateTime={freshLink.expiresAt} className='font-semibold whitespace-nowrap'>
              {formatIST(freshLink.expiresAt, { withYear: false })}
            </time>
          </p>
          {remaining !== null && (
            <p className='inline-flex items-center gap-1.5 font-semibold whitespace-nowrap tabular-nums'>
              {expired && <Spinner className='size-3.5' aria-hidden='true' role='presentation' />}
              {expired ? 'Checking…' : formatRemaining(remaining)}
            </p>
          )}
        </div>
        <p className='text-[13px]'>
          {localTimeZone && <>That&apos;s {formatLocal(freshLink.expiresAt, localTimeZone)} your time. </>}
          No further rescheduling — this was your one-time reschedule for this interview.
        </p>
      </Banner>

      {alreadyUsedNotice && (
        <Callout tone='info' icon={InfoIcon} title='You already have a new link.'>
          You&apos;ve already used your one-time reschedule, so we didn&apos;t create another one. Here&apos;s the link
          you already have.
        </Callout>
      )}

      {needsLaptop && (
        <Callout tone='info' icon={LaptopIcon} title='Open this link on a laptop or desktop.'>
          Coding interviews need a full keyboard, so they don&apos;t work on phones. Copy or share the link below and
          open it in Chrome on your computer.
        </Callout>
      )}

      <InAppBrowserNotice />

      <div className='space-y-4'>
        <Button
          variant='blue'
          size='xl'
          className={cn(primaryAction, 'aria-disabled:pointer-events-none aria-disabled:opacity-60')}
          asChild
        >
          <a href={expired ? undefined : freshLink.url} aria-disabled={expired || undefined}>
            <PlayIcon aria-hidden='true' className='fill-current' />
            Start Interview
          </a>
        </Button>
        <CopyLink url={freshLink.url} showShare={handheld} />
      </div>

      <p className='text-muted-foreground text-xs leading-relaxed'>
        You only need to <span className='text-foreground font-medium'>start</span> before the deadline · takes about{' '}
        {formatDuration(interview.durationMinutes)} · we&apos;ll remind you on WhatsApp and email
      </p>
    </div>
  )
}

export default FreshLinkView

'use client'

// React Imports
import { useCallback, useEffect, useRef, useState } from 'react'

// Third-party Imports
import { CalendarX2Icon } from 'lucide-react'

// Component Imports
import { Skeleton } from '@newtonschool/koyo-ui/skeleton'

import type { MockOptions, PrototypeScenario, RescheduleApi, RescheduleStatus } from './reschedule-data'
import { createMockRescheduleApi, formatIST, platformSupport, prototypeScenarios } from './reschedule-data'
import { NeedHelpLine, RescheduleFooter, RescheduleHeader } from './reschedule-ui'
import type { RescheduleFormValues, SubmitFailure } from './reschedule-form'
import RescheduleForm, { OneTimeBanner } from './reschedule-form'
import FreshLinkView from './fresh-link-view'
import { LoadErrorView, showsSupportActions, StatusView } from './status-view'
import InterviewSummary, { PageHeading } from './interview-summary'
import PrototypeControls from './prototype-controls'

type View =
  | { phase: 'loading' }
  | { phase: 'load-error' }
  | { phase: 'ready'; status: RescheduleStatus; justIssued?: boolean; alreadyUsedNotice?: boolean }

const createIdempotencyKey = () =>
  typeof crypto !== 'undefined' && 'randomUUID' in crypto
    ? crypto.randomUUID()
    : `${Date.now()}-${Math.random().toString(36).slice(2)}`

type PendingRequest = RescheduleFormValues & { idempotencyKey: string }

/** Compares two statuses while ignoring the server clock stamp, which changes on every response. */
const sameStatus = (a: RescheduleStatus, b: RescheduleStatus) =>
  JSON.stringify({ ...a, serverTime: undefined }) === JSON.stringify({ ...b, serverTime: undefined })

const pillWidths = ['w-72', 'w-56', 'w-52', 'w-96', 'w-20']

const LoadingView = () => (
  <div className='space-y-6' aria-hidden='true'>
    <div className='space-y-5'>
      <Skeleton className='h-6 w-56' />
      <div className='flex items-center gap-4 sm:gap-5'>
        <Skeleton className='size-14 shrink-0 rounded-2xl sm:size-20' />
        <div className='flex-1 space-y-3'>
          <Skeleton className='h-8 w-2/3' />
          <Skeleton className='h-4 w-1/2' />
        </div>
      </div>
    </div>
    <Skeleton className='h-12 w-full rounded-lg' />
    <div className='space-y-3'>
      <Skeleton className='h-5 w-64' />
      <div className='flex flex-wrap gap-2.5'>
        {pillWidths.map(width => (
          <Skeleton key={width} className={`h-10 max-w-full rounded-full ${width}`} />
        ))}
      </div>
    </div>
    <Skeleton className='h-[4.5rem] w-full rounded-lg' />
    <Skeleton className='h-12 w-full rounded-lg' />
  </div>
)

/**
 * Candidate-facing rescheduling page for AI interviews. One page renders every state from the
 * PRD (§7): the reason form, the fresh-link confirmation and the shared status screens.
 * Pass an `api` backed by the platform's reschedule endpoints in production. Keep `api` stable
 * (create it once or memoise it): a new `api` reloads the page and clears the form.
 */
export const InterviewReschedule = ({ api }: { api: RescheduleApi }) => {
  // States
  const [view, setView] = useState<View>({ phase: 'loading' })
  const [clockOffset, setClockOffset] = useState(0)
  const [recheckedDeadline, setRecheckedDeadline] = useState<string | null>(null)

  // Refs
  const headingRef = useRef<HTMLHeadingElement>(null)
  const focusHeadingRef = useRef(false)
  const submittingRef = useRef(false)
  const phaseRef = useRef<View['phase']>('loading')

  // Every load, refresh and submit takes a ticket; only the latest one may update the view, so a slow
  // response can never take the page back to an older state (PRD §11: late or out-of-order status).
  const ticketRef = useRef(0)

  // The request awaiting an answer. While its outcome is unknown, retries resend it unchanged with the
  // same idempotency key, so the server can recognise it (PRD FR-09). A definite answer clears it.
  const pendingRequestRef = useRef<PendingRequest | null>(null)

  useEffect(() => {
    phaseRef.current = view.phase
  }, [view.phase])

  const showView = useCallback((next: View, { moveFocus = true } = {}) => {
    if (next.phase === 'ready' && next.status.serverTime) {
      setClockOffset(new Date(next.status.serverTime).getTime() - Date.now())
    }

    focusHeadingRef.current = moveFocus
    setView(next)
  }, [])

  const load = useCallback(
    async ({ moveFocus = false } = {}) => {
      const ticket = ++ticketRef.current

      phaseRef.current = 'loading'
      setView({ phase: 'loading' })

      try {
        const next = await api.getStatus()

        if (ticket === ticketRef.current) showView({ phase: 'ready', status: next }, { moveFocus })
      } catch {
        if (ticket === ticketRef.current) showView({ phase: 'load-error' }, { moveFocus })
      }
    },
    [api, showView]
  )

  useEffect(() => {
    load()
  }, [load])

  // Re-check quietly when the candidate comes back to the tab (they may have used the link elsewhere).
  useEffect(() => {
    const refresh = async () => {
      // Never cut in on a load or a submit that is already running.
      if (document.visibilityState !== 'visible' || submittingRef.current || phaseRef.current !== 'ready') return

      const ticket = ++ticketRef.current

      try {
        const next = await api.getStatus()

        if (ticket !== ticketRef.current) return

        if (next.serverTime) setClockOffset(new Date(next.serverTime).getTime() - Date.now())

        setView(current => {
          if (current.phase === 'ready' && sameStatus(current.status, next)) return current
          focusHeadingRef.current = current.phase !== 'ready' || current.status.state !== next.state

          return { phase: 'ready', status: next }
        })
      } catch {
        // Keep what's on screen; the next visit or action will try again.
      }
    }

    const handlePageShow = (event: PageTransitionEvent) => {
      if (event.persisted) refresh()
    }

    document.addEventListener('visibilitychange', refresh)
    window.addEventListener('pageshow', handlePageShow)

    return () => {
      document.removeEventListener('visibilitychange', refresh)
      window.removeEventListener('pageshow', handlePageShow)
    }
  }, [api])

  // Keep the tab title in step with the screen, so the state is clear from the tab bar and to screen readers.
  useEffect(() => {
    const heading = headingRef.current?.textContent

    if (heading) document.title = `${heading} · Koyo AI Interviews`
  }, [view])

  // Move focus to the new heading after a state change so screen readers announce it.
  useEffect(() => {
    if (!focusHeadingRef.current || view.phase === 'loading') return
    focusHeadingRef.current = false

    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches

    window.scrollTo({ top: 0, behavior: reduceMotion ? 'instant' : 'smooth' })
    headingRef.current?.focus({ preventScroll: true })
  }, [view])

  // When a deadline passes on screen, ask the server once. If it says the link still works (the device
  // clock was ahead), trust it and don't ask again for the same deadline.
  const handleDeadlinePassed = useCallback(
    (deadline: string) => {
      if (recheckedDeadline === deadline) return
      setRecheckedDeadline(deadline)
      load({ moveFocus: true })
    },
    [recheckedDeadline, load]
  )

  const submit = async (values: RescheduleFormValues): Promise<SubmitFailure | void> => {
    const ticket = ++ticketRef.current
    const isCurrent = () => ticket === ticketRef.current
    const request = pendingRequestRef.current ?? { ...values, idempotencyKey: createIdempotencyKey() }

    pendingRequestRef.current = request

    try {
      const result = await api.submit(request)

      if (!result.ok && result.code === 'temporary') {
        // Nothing was created, so the next attempt is a new request (and may carry a different reason).
        pendingRequestRef.current = null

        return 'temporary-error'
      }

      pendingRequestRef.current = null

      if (result.ok) {
        showView({ phase: 'ready', status: result.status, justIssued: true })

        return
      }

      showView({ phase: 'ready', status: result.status, alreadyUsedNotice: result.code === 'already-used' })
    } catch {
      // The request may or may not have reached the server. Re-check before deciding — never show a false success.
      try {
        const next = await api.getStatus()

        if (next.state === 'eligible') return 'temporary-error'

        pendingRequestRef.current = null

        if (isCurrent()) showView({ phase: 'ready', status: next, justIssued: next.state === 'fresh-link-active' })
      } catch {
        return 'unknown-outcome'
      }
    }
  }

  const handleSubmit = async (values: RescheduleFormValues) => {
    submittingRef.current = true

    try {
      return await submit(values)
    } finally {
      submittingRef.current = false
    }
  }

  const status = view.phase === 'ready' ? view.status : null
  const interview = status && status.state !== 'invalid-link' ? status.interview : null

  let main

  if (view.phase === 'loading') {
    main = <LoadingView />
  } else if (view.phase === 'load-error') {
    main = <LoadErrorView headingRef={headingRef} onRetry={() => load({ moveFocus: true })} />
  } else if (view.status.state === 'eligible') {
    const { interview: details } = view.status

    main = (
      <div className='space-y-5'>
        <PageHeading headingRef={headingRef}>Reschedule your interview</PageHeading>
        <InterviewSummary
          interview={details}
          detail={{
            icon: CalendarX2Icon,
            label: (
              <>
                Link expired{' '}
                <time dateTime={details.originalLinkExpiresAt}>
                  {formatIST(details.originalLinkExpiresAt, { withYear: false })}
                </time>
              </>
            )
          }}
        />
        <OneTimeBanner interview={details} />
        <div className='pt-2'>
          <RescheduleForm interview={details} onSubmit={handleSubmit} />
        </div>
      </div>
    )
  } else if (view.status.state === 'fresh-link-active') {
    main = (
      <FreshLinkView
        interview={view.status.interview}
        freshLink={view.status.freshLink}
        justIssued={!!view.justIssued}
        alreadyUsedNotice={view.alreadyUsedNotice}
        headingRef={headingRef}
        clockOffset={clockOffset}
        deadlineConfirmed={recheckedDeadline === view.status.freshLink.expiresAt}
        onDeadlinePassed={handleDeadlinePassed}
      />
    )
  } else {
    main = (
      <StatusView
        status={view.status}
        headingRef={headingRef}
        clockOffset={clockOffset}
        deadlineConfirmed={
          view.status.state === 'original-link-active' &&
          recheckedDeadline === view.status.interview.originalLinkExpiresAt
        }
        onDeadlinePassed={handleDeadlinePassed}
      />
    )
  }

  const support = interview?.support ?? (status?.state === 'invalid-link' ? status.support : platformSupport)

  return (
    <div className='bg-background flex min-h-screen flex-col'>
      <RescheduleHeader helpHref='#help' />

      {/* Lives outside the swapped content so screen readers hear it every time the page reloads its status. */}
      <p role='status' className='sr-only'>
        {view.phase === 'loading' ? 'Loading your interview details…' : ''}
      </p>

      <main className='flex-1'>
        <div className='mx-auto max-w-4xl px-4 pt-6 pb-10 sm:px-6 lg:px-8'>
          <div className='max-w-3xl'>
            {main}

            {view.phase !== 'loading' && !(status && showsSupportActions(status)) && (
              <NeedHelpLine
                support={support}
                className='mt-6 border-t pt-4'
                note={
                  status?.state === 'eligible' ? (
                    <>
                      Not {status.interview.candidateFirstName}? Please don&apos;t use this link — contact the hiring
                      team instead.
                    </>
                  ) : undefined
                }
              />
            )}
          </div>
        </div>
      </main>

      <RescheduleFooter />
    </div>
  )
}

const isScenario = (value: string | null): value is PrototypeScenario =>
  prototypeScenarios.some(scenario => scenario.value === value)

/** Remounting this (new `key`) gives the prototype a fresh mock backend. */
const MockedReschedule = ({
  scenario,
  kind,
  getNetwork
}: Pick<MockOptions, 'scenario' | 'kind'> & {
  getNetwork: () => Pick<MockOptions, 'failFirstSubmit' | 'latencyMs'>
}) => {
  const [api] = useState(() => createMockRescheduleApi({ scenario, kind }, getNetwork))

  return <InterviewReschedule api={api} />
}

/** Block preview: the page wired to a mock API plus controls for walking through every state. */
const InterviewRescheduleDemo = () => {
  // States
  const [options, setOptions] = useState<MockOptions>({
    scenario: 'eligible',
    kind: 'operational',
    failFirstSubmit: false,
    latencyMs: 900
  })

  const [run, setRun] = useState(0)

  // Refs
  const networkRef = useRef({ failFirstSubmit: options.failFirstSubmit, latencyMs: options.latencyMs })

  useEffect(() => {
    networkRef.current = { failFirstSubmit: options.failFirstSubmit, latencyMs: options.latencyMs }
  }, [options.failFirstSubmit, options.latencyMs])

  // Deep links such as `?state=final-link-expired&kind=coding` open a specific state.
  useEffect(() => {
    const params = new URLSearchParams(window.location.search)
    const state = params.get('state')
    const kind = params.get('kind')

    setOptions(current => ({
      ...current,
      scenario: isScenario(state) ? state : current.scenario,
      kind: kind === 'coding' || kind === 'operational' ? kind : current.kind
    }))
  }, [])

  const getNetwork = useCallback(() => networkRef.current, [])

  return (
    <>
      <MockedReschedule
        key={`${run}-${options.scenario}-${options.kind}`}
        scenario={options.scenario}
        kind={options.kind}
        getNetwork={getNetwork}
      />
      <PrototypeControls options={options} onChange={setOptions} onRestart={() => setRun(current => current + 1)} />
    </>
  )
}

export default InterviewRescheduleDemo

// React Imports
import type { ReactNode, Ref } from 'react'

// Third-party Imports
import type { LucideIcon } from 'lucide-react'
import { BriefcaseBusinessIcon, ClockIcon, CodeXmlIcon, VideoIcon } from 'lucide-react'

// Util Imports
import { cn } from '@/lib/utils'

import type { InterviewDetails } from './reschedule-data'
import { formatDurationShort } from './reschedule-data'

/** The screen's small title, like "Modify your reservation". Focus moves here when the state changes. */
export const PageHeading = ({
  headingRef,
  children
}: {
  headingRef?: Ref<HTMLHeadingElement>
  children: ReactNode
}) => (
  <h1 ref={headingRef} tabIndex={-1} className='text-lg font-semibold tracking-tight outline-none'>
    {children}
  </h1>
)

export const CompanyTile = ({ interview, className }: { interview: InterviewDetails; className?: string }) => (
  <span
    className={cn(
      'ring-border grid aspect-square size-14 shrink-0 place-items-center rounded-2xl text-xl font-bold tracking-tight ring-1 sm:size-20 sm:text-2xl',
      interview.company.tileClassName,
      className
    )}
    aria-hidden='true'
  >
    {interview.company.monogram}
  </span>
)

export type MetaDetail = { icon: LucideIcon; label: ReactNode }

const MetaItem = ({ icon: Icon, children }: { icon: LucideIcon; children: ReactNode }) => (
  <li className='flex items-center gap-1.5'>
    <Icon className='size-4 shrink-0' aria-hidden='true' />
    <span>{children}</span>
  </li>
)

/**
 * Company logo, role and one meta row: company · duration · a state detail such as the expiry, or else
 * the interview title (e.g. the round), so every state opens with the same summary of the invitation.
 */
const InterviewSummary = ({ interview, detail }: { interview: InterviewDetails; detail?: MetaDetail }) => (
  <section
    aria-label='Interview details'
    className='grid grid-cols-[auto_minmax(0,1fr)] items-center gap-x-4 gap-y-3 sm:gap-x-5 sm:gap-y-1.5'
  >
    <CompanyTile interview={interview} className='sm:row-span-2' />
    <h2 className='text-2xl leading-tight font-semibold tracking-tight sm:self-end sm:text-3xl'>{interview.role}</h2>
