 * variables are active, with or without a `.dark` class.
 */
const tint = {
  banner:
    'bg-[color-mix(in_oklab,var(--tone)_10%,var(--background))] text-[color-mix(in_oklab,var(--tone)_25%,var(--foreground))]',
  callout:
