  icon: 'text-[color-mix(in_oklab,var(--tone)_85%,var(--foreground))]'
}

const neutral = {
  banner: 'bg-muted text-foreground',
  callout: 'border-border bg-muted/50 text-foreground',
  icon: 'text-muted-foreground'
}

